    hl.exec_cmd("brightnessctl s 10")
    hl.exec_cmd("~/.local/bin/battery_notify.sh")
    hl.exec_cmd("~/.local/bin/setup_backlight.sh")
    hl.exec_cmd("waybar")
    hl.exec_cmd("hyprpaper")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
